import XCTest
import Foundation
@testable import TechnichromeCore

/// Compares the Swift engine against the Python prototype using fixtures generated by
/// tools/colorscience/export_fixtures.py (parameters + expected outputs for a set of inputs).
final class PythonParityTests: XCTestCase {
    struct Fixture: Decodable {
        struct Sample: Decodable { let input: [Double]; let dye: [Double]; let key: Double; let output: [Double] }
        let parameters: EngineParameters
        let lutDimension: Int
        let displaySpace: String
        let samples: [Sample]
    }

    func loadFixture() throws -> Fixture? {
        guard let url = Bundle.module.url(forResource: "parity", withExtension: "json", subdirectory: "Fixtures") else { return nil }
        return try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }

    func testMatchesPythonPrototype() throws {
        guard let f = try loadFixture() else {
            throw XCTSkip("no parity fixture generated yet")
        }
        let space: PrintModel.DisplaySpace = f.displaySpace == "srgb" ? .sRGB : .displayP3
        let pipe = ReferencePipeline(parameters: f.parameters, lutDimension: f.lutDimension, displaySpace: space)
        var maxErr = 0.0
        for s in f.samples {
            let input = SIMD3(s.input[0], s.input[1], s.input[2])
            let (dye, key) = pipe.densities(sceneLinear: input)
            XCTAssertEqual(dye.x, s.dye[0], accuracy: 2e-3, "cyan density for \(s.input)")
            XCTAssertEqual(dye.y, s.dye[1], accuracy: 2e-3, "magenta density for \(s.input)")
            XCTAssertEqual(dye.z, s.dye[2], accuracy: 2e-3, "yellow density for \(s.input)")
            XCTAssertEqual(key, s.key, accuracy: 2e-3, "key density for \(s.input)")
            let out = pipe.develop(sceneLinear: input)
            for i in 0..<3 {
                let err = abs(out[i] - s.output[i])
                maxErr = max(maxErr, err)
                XCTAssertEqual(out[i], s.output[i], accuracy: 4e-3, "output channel \(i) for \(s.input)")
            }
        }
        print("max |Swift - Python| output error: \(maxErr)")
    }
}
